// Close is to release resource of ConnPool, it is executed when client is closed.
func (p *connPool) Close() error {
	p.conns.Range(func(addr, trans interface{}) bool {
		p.conns.Delete(addr)
		trans.(*transports).close()
		return true
	})
	return nil
}

// Dump returns diagnostic information about the connection pool state.
// It provides visibility into pool size, active connections, and connection status per address.
func (p *connPool) Dump() map[string]interface{} {
	dump := make(map[string]interface{})
	dump["remote_service"] = p.remoteService
	dump["pool_size"] = p.size
	dump["short_conn"] = p.connOpts.ShortConn

	connections := make(map[string]interface{})
	p.conns.Range(func(key, value interface{}) bool {
		addr := key.(string)
		trans := value.(*transports)

		connInfo := make(map[string]interface{})
		connInfo["size"] = trans.size
		connInfo["index"] = atomic.LoadUint32(&trans.index)

		activeConns := 0
		inactiveConns := 0
		nullConns := 0

		for i := 0; i < int(trans.size); i++ {
			if trans.cliTransports[i] == nil {
				nullConns++
			} else if trans.cliTransports[i].(grpc.IsActive).IsActive() {
				activeConns++
			} else {
				inactiveConns++
			}
		}

		connInfo["active"] = activeConns
		connInfo["inactive"] = inactiveConns
		connInfo["null"] = nullConns
		connections[addr] = connInfo
		return true
	})

	dump["connections"] = connections
	dump["total_addresses"] = len(connections)
	return dump
}

// newTLSConn constructs a client-side TLS connection and performs handshake.
func newTLSConn(conn net.Conn, tlsCfg *tls.Config) (net.Conn, error) {
	tlsConn := tls.Client(conn, tlsCfg)
	if err := tlsConn.Handshake(); err != nil {
		return nil, err
	}
	return tlsConn, nil
}

