// ReadFrame reads a single frame. The returned Frame is only valid
// until the next call to ReadFrame.
//
// If the frame is larger than previously set with SetMaxReadFrameSize, the
// returned error is ErrFrameTooLarge. Other errors may be of type
// ConnectionError, StreamError, or anything else from the underlying
// reader.
func (fr *Framer) ReadFrame() (http2.Frame, error) {
	fr.errDetail = nil

	fh, err := readFrameHeader(fr.reader)
	if err != nil {
		return nil, fmt.Errorf("failed to read frame header: %w", err)
	}
	if fh.Length > fr.maxReadSize {
		return nil, fmt.Errorf("frame too large (type=%s, streamID=%d, length=%d, max=%d): %w",
			fh.Type, fh.StreamID, fh.Length, fr.maxReadSize, http2.ErrFrameTooLarge)
	}
	// payload := fr.getReadBuf(fh.Length)
	var f http2.Frame
	if fh.Type == http2.FrameData {
		f, err = parseDataFrame(fr.frameCache, fh, fr.reader)
	} else {
		var payload []byte
		payload, err = fr.reader.Next(int(fh.Length))
		if err != nil {
			return nil, fmt.Errorf("failed to read frame payload (type=%s, streamID=%d, length=%d): %w",
				fh.Type, fh.StreamID, fh.Length, err)
		}
		f, err = typeFrameParser(fh.Type)(fr.frameCache, fh, payload)
	}
	if err != nil {
		if ce, ok := err.(connError); ok {
			return nil, fr.connError(ce.Code, ce.Reason)
		}
		return nil, fmt.Errorf("failed to parse frame (type=%s, streamID=%d): %w",
			fh.Type, fh.StreamID, err)
	}
	if err = fr.checkFrameOrder(f); err != nil {
		return nil, err
	}
	if fh.Type == http2.FrameHeaders && fr.ReadMetaHeaders != nil {
		return fr.readMetaFrame(f.(*HeadersFrame))
	}
	return f, nil
}

