// WithUnaryOptions wraps multiple UnaryOption into a single Option.
// This allows unary-specific options to be grouped and applied together.
func WithUnaryOptions(opts ...UnaryOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithUnaryOptions")
		for _, opt := range opts {
			opt.F(o, di)
		}
	}}
}

// WithUnaryRPCTimeout sets the RPC timeout for unary calls.
func WithUnaryRPCTimeout(d time.Duration) UnaryOption {
	return UnaryOption{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryRPCTimeout(%dms)", d.Milliseconds()))
		rpcinfo.AsMutableRPCConfig(o.Configs).SetRPCTimeout(d)
		o.Locks.Bits |= rpcinfo.BitRPCTimeout
	}}
}

// WithUnaryMiddleware adds middleware for unary client calls.
func WithUnaryMiddleware(mw endpoint.UnaryMiddleware) UnaryOption {
	return UnaryOption{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddleware(%+v)", utils.GetFuncName(mw)))
		mwb := func(ctx context.Context) endpoint.Middleware {
			return endpoint.Middleware(mw)
		}
		o.MWBs = append(o.MWBs, mwb)
	}}
}

// WithUnaryMiddlewareBuilder adds a middleware builder for unary client calls.
// The builder is invoked with the request context to create the middleware.
func WithUnaryMiddlewareBuilder(mwb endpoint.MiddlewareBuilder) UnaryOption {
	return UnaryOption{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddlewareBuilder(%+v)", utils.GetFuncName(mwb)))
		o.MWBs = append(o.MWBs, mwb)
	}}
}

