// MiddlewareBuilder creates a Middleware based on the given context.
type MiddlewareBuilder = endpoint.MiddlewareBuilder

// StreamEndpoint represents a server streaming endpoint that handles a ServerStream.
type StreamEndpoint func(ctx context.Context, st streaming.ServerStream) (err error)

// StreamRecvEndpoint represents a server receiving endpoint for streaming operations.
// It processes messages received from the client through the ServerStream.
type StreamRecvEndpoint func(ctx context.Context, stream streaming.ServerStream, message interface{}) (err error)

// StreamSendEndpoint represents a server sending endpoint for streaming operations.
// It sends messages to the client through the ServerStream.
type StreamSendEndpoint func(ctx context.Context, stream streaming.ServerStream, message interface{}) (err error)

// EqualsTo checks if two StreamRecvEndpoint instances are functionally equivalent.
func (e StreamRecvEndpoint) EqualsTo(e2 StreamRecvEndpoint) bool {
	// Function pointer comparison - limited but safe
	return &e == &e2
}

// EqualsTo checks if two StreamSendEndpoint instances are functionally equivalent.
func (e StreamSendEndpoint) EqualsTo(e2 StreamSendEndpoint) bool {
	// Function pointer comparison - limited but safe
	return &e == &e2
}

// StreamMiddleware wraps a StreamEndpoint with additional functionality.
type StreamMiddleware func(next StreamEndpoint) StreamEndpoint

// StreamMiddlewareBuilder creates a StreamMiddleware based on the given context.
type StreamMiddlewareBuilder func(ctx context.Context) StreamMiddleware

// StreamRecvMiddleware wraps a StreamRecvEndpoint with additional functionality.
type StreamRecvMiddleware func(next StreamRecvEndpoint) StreamRecvEndpoint

// StreamRecvMiddlewareBuilder creates a StreamRecvMiddleware based on the given context.
type StreamRecvMiddlewareBuilder func(ctx context.Context) StreamRecvMiddleware

// StreamSendMiddleware wraps a StreamSendEndpoint with additional functionality.
type StreamSendMiddleware func(next StreamSendEndpoint) StreamSendEndpoint

// StreamSendMiddlewareBuilder creates a StreamSendMiddleware based on the given context.
type StreamSendMiddlewareBuilder func(ctx context.Context) StreamSendMiddleware

// StreamChain creates a single StreamMiddleware from a chain of middlewares.
func StreamChain(mws ...StreamMiddleware) StreamMiddleware {
	return func(next StreamEndpoint) StreamEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// StreamRecvChain creates a single StreamRecvMiddleware from a chain of middlewares.
func StreamRecvChain(mws ...StreamRecvMiddleware) StreamRecvMiddleware {
	return func(next StreamRecvEndpoint) StreamRecvEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// StreamSendChain creates a single StreamSendMiddleware from a chain of middlewares.
func StreamSendChain(mws ...StreamSendMiddleware) StreamSendMiddleware {
	return func(next StreamSendEndpoint) StreamSendEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

