func (fr *Framer) readAndCheckFrameHeader() (http2.FrameHeader, error) {
	buf, err := fr.reader.Next(frameHeaderLen)
	if err != nil {
		return http2.FrameHeader{}, fmt.Errorf("failed to read frame header: %w", err)
	}

	fh := http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
	}

	// Check frame size and provide detailed error with hex dump if too large
	if fh.Length > fr.maxReadSize {
		// Peek at payload for debugging (up to 32 bytes)
		peekSize := 32
		if int(fh.Length) < peekSize {
			peekSize = int(fh.Length)
		}

		var hexDump string
		if peekSize > 0 {
			if peekBuf, peekErr := fr.reader.Peek(peekSize); peekErr == nil {
				hexDump = fmt.Sprintf("\nFirst %d bytes (hex): % x", len(peekBuf), peekBuf)
			}
		}

		return http2.FrameHeader{}, fmt.Errorf("frame too large (type=%s, streamID=%d, length=%d, max=%d)%s: %w",
			fh.Type, fh.StreamID, fh.Length, fr.maxReadSize, hexDump, http2.ErrFrameTooLarge)
	}

	return fh, nil
}

