// WithRecvTimeout sets the receive timeout for streaming calls at the call level.
// This timeout applies to individual Recv() operations on the stream.
func WithRecvTimeout(d time.Duration) callopt.Option {
	return callopt.Option{
		F: func(o *client.Options, di *utils.Slice) {
			di.Push(fmt.Sprintf("streamcall.WithRecvTimeout(%dms)", d.Milliseconds()))
			// Set the read/write timeout which applies to streaming recv operations
			rpcinfo.AsMutableRPCConfig(o.Configs).SetReadWriteTimeout(d)
			o.Locks.Bits |= rpcinfo.BitReadWriteTimeout
		},
	}
}

