// WithTTHeaderStreamingTransportOptions sets transport-specific options for TTHeader streaming.
// This configures the underlying transport layer for TTHeaderStreaming protocol.
// Note: remote.ClientOption does not support functional composition, so this stores
// the last provided option set directly.
func WithTTHeaderStreamingTransportOptions(opts ...remote.ClientOption) TTHeaderStreamingOption {
	return TTHeaderStreamingOption{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithTTHeaderStreamingTransportOptions(count=%d)", len(opts)))
		// Store the last option if provided (remote.ClientOption doesn't support chaining)
		if len(opts) > 0 {
			o.RemoteOpt = &opts[len(opts)-1]
		}
	}}
}

